function M.rgb_to_hex(r, g, b)
  local function clamp(n)
    return math.max(0, math.min(255, math.floor(n + 0.5)))
  end
  return string.format('#%02x%02x%02x', clamp(r), clamp(g), clamp(b))
end

function M.get_stats()
  return vim.deepcopy(stats)
end

