function M.get_delay(bufnr)
  if type(bufnr) ~= 'number' or bufnr < 0 then
    return nil
  end

  return calculate_delay(bufnr)
end

function M.get_config()
  return vim.deepcopy(config)
end

function M.create_debounced(fn, custom_delay)
  return function(bufnr, ...)
    local args = { ... }

    M.debounce(bufnr, function()
      fn(bufnr, unpack(args))
    end, custom_delay)
  end
end

function M.setup_auto_cleanup()
  local group = autocmd.augroup.create.clear('ColorMyAsciiDebounce')

  autocmd.create('BufDelete', function(args)
    M.cancel(args.buf)
  end, {
    group = group,
    desc = 'Cleanup debounce timers on buffer delete',
  })
end

function M.clear(bufnr)
  pcall(api.nvim_buf_clear_namespace, bufnr, ns, 0, -1)
end

local function set_line(bufnr, row, group, priority)
  pcall(api.nvim_buf_set_extmark, bufnr, ns, row, 0, {
    line_hl_group = group,
    priority = priority,
  })
end

local function int_to_hex(n)
  return string.format('#%06x', n)
end

local function css_token(group)
  return (group:gsub('[^%w_-]', '_'))
end

local function html_escape(text)
  return (text:gsub('[&<>]', HTML_ESCAPE))
end

function M.scheme_exists(scheme_name)
  return AVAILABLE_SCHEMES[scheme_name:lower()] ~= nil
end

function M.is_theme(name)
  return M.presets[name] ~= nil
end
